   class RestrictionsDetector : Detector(), XmlScanner {
       override fun getApplicableElements(): Collection<String>? = listOf(TAG_RESTRICTIONS)

       override fun visitElement(context: XmlContext, element: Element) {
           // element is <restrictions>
           // Check children
           val keys = mutableSetOf<String>()
           var child = DomUtil.getFirstChildTag(element)
           while (child != null) {
               if (child.tagName == TAG_RESTRICTION) {
                   checkRestriction(context, child, keys)
               } else {
                   context.report(
                       ISSUE,
                       child,
                       context.getLocation(child),
                       "Invalid tag `${child.tagName}`; expected `<restriction>`"
                   )
               }
               child = DomUtil.getNextTag(child)
           }
       }

       private fun checkRestriction(context: XmlContext, element: Element, keys: MutableSet<String>) {
           // Check required attributes
           val key = element.getAttributeNS(ANDROID_URI, ATTR_KEY)
           val title = element.getAttributeNS(ANDROID_URI, ATTR_TITLE)
           val type = element.getAttributeNS(ANDROID_URI, ATTR_RESTRICTION_TYPE)

           if (key.isNullOrEmpty()) {
               context.report(ISSUE, element, context.getLocation(element), "Missing required attribute `android:key`")
           } else if (!keys.add(key)) {
               context.report(ISSUE, element, context.getLocation(element), "Duplicate key `$key`")
           }

           if (title.isNullOrEmpty()) {
               context.report(ISSUE, element, context.getLocation(element), "Missing required attribute `android:title`")
           }

           if (type.isNullOrEmpty()) {
               context.report(ISSUE, element, context.getLocation(element), "Missing required attribute `android:restrictionType`")
           } else {
               checkType(context, element, type)
           }

           // Check nested restrictions for bundle/bundle_array
           if (type == "bundle" || type == "bundle_array") {
               var child = DomUtil.getFirstChildTag(element)
               val nestedKeys = mutableSetOf<String>()
               while (child != null) {
                   if (child.tagName == TAG_RESTRICTION) {
                       checkRestriction(context, child, nestedKeys)
                   } else {
                       context.report(ISSUE, child, context.getLocation(child), "Invalid tag `${child.tagName}` inside bundle; expected `<restriction>`")
                   }
                   child = DomUtil.getNextTag(child)
               }
           }
       }

       private fun checkType(context: XmlContext, element: Element, type: String) {
           val validTypes = setOf("bool", "string", "integer", "choice", "multi-select", "bundle", "bundle_array")
           if (type !in validTypes) {
               context.report(
                   ISSUE,
                   element,
                   context.getLocation(element.getAttributeNodeNS(ANDROID_URI, ATTR_RESTRICTION_TYPE)),
                   "Invalid restriction type `$type`; must be one of ${validTypes.joinToString()}"
               )
           }

           // Check choice/multi-select requirements
           if (type == "choice" || type == "multi-select") {
               val entries = element.getAttributeNS(ANDROID_URI, ATTR_ENTRIES)
               val entryValues = element.getAttributeNS(ANDROID_URI, ATTR_ENTRY_VALUES)
               if (entries.isNullOrEmpty()) {
                   context.report(ISSUE, element, context.getLocation(element), "Missing required attribute `android:entries` for type `$type`")
               }
               if (entryValues.isNullOrEmpty()) {
                   context.report(ISSUE, element, context.getLocation(element), "Missing required attribute `android:entryValues` for type `$type`")
               }
           }
       }

       companion object {
           private const val TAG_RESTRICTIONS = "restrictions"
           private const val TAG_RESTRICTION = "restriction"
           private const val ATTR_KEY = "key"
           private const val ATTR_TITLE = "title"
           private const val ATTR_RESTRICTION_TYPE = "restrictionType"
           private const val ATTR_ENTRIES = "entries"
           private const val ATTR_ENTRY_VALUES = "entryValues"
       }
   }
   ```

